function show(id){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');window.scrollTo(0,0)}
function esc(s){return String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function norm(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function card(h,t){return `<div class="result"><button class="copy" data-copy>📋 Copiar</button><h4>${h}</h4><p>${t}</p></div>`}
async function copyResult(btn){const p=btn.closest('.result')?.querySelector('p');if(!p)return;const text=p.innerText;try{await navigator.clipboard.writeText(text)}catch{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove()}btn.textContent='✓ Copiado';setTimeout(()=>btn.textContent='📋 Copiar',1000)}
function fmtDate(v){if(!v)return 'Fecha por confirmar';const [y,m,d]=v.split('-');return `${d}/${m}/${y}`}

function scoreTopic(input,item){const n=norm(input);let score=0;item.keywords.forEach(k=>{const nk=norm(k);if(n===nk)score+=10;else if(n.includes(nk))score+=6;else if(nk.includes(n))score+=3});const title=norm(item.title);if(n.includes(title)||title.includes(n))score+=5;return score}
function matchTopic(input){let best=null,bestScore=0;Object.entries(LIBRARY).forEach(([key,item])=>{const s=scoreTopic(input,item);if(s>bestScore){best={key,item};bestScore=s}});return bestScore>0?best:null}

let sermonVersion=0;
function sermon(alternate=false){
 if(alternate)sermonVersion++;
 const topic=val('sTopic')||'Fe';
 const match=matchTopic(topic);
 const aud=$('sAudience').value,dur=$('sDuration').value,dep=$('sDepth').value,typ=$('sType').value;
 if(!match){
   const available=Object.values(LIBRARY).map(x=>x.title).join(' · ');
   $('sOut').innerHTML=card('⚠️ Tema todavía no disponible',`Pastoral+ V2.5 trabaja con una biblioteca pastoral local para garantizar coherencia sin IA.\n\nNo encontré una coincidencia suficientemente clara para “${esc(topic)}”.\n\nPrueba con alguno de estos temas:\n${available}`);
   return;
 }
 const item=match.item;
 const v=item.variants[sermonVersion%item.variants.length];
 let html='';
 html+=card('📖 Título sugerido',v.title);
 html+=card('🎯 Idea central',v.idea);
 html+=card('📚 Texto base',v.base);
 html+=card('📚 Textos de apoyo',v.supports.join(' · '));
 html+=card('🎤 Introducción',`Mensaje ${typ.toLowerCase()} de ${dur} minutos para ${aud.toLowerCase()}, con profundidad ${dep.toLowerCase()}.\n\n${v.intro}`);
 v.points.forEach((p,i)=>{html+=card(`${i+1}. ${p[0]}`,`📖 ${p[1]}\n\n${p[2]}\n\n💭 Pregunta de conexión\n${p[3]}`)});
 html+=card('🔥 Frases para enfatizar',v.quotes.map(q=>'• '+q).join('\n'));
 html+=card('🎯 Aplicación final',v.call);
 html+=card('🙏 Oración final',v.prayer);
 html+=card('ℹ️ Cómo usar este bosquejo',`Pastoral+ prepara una ruta de sermón completa. El pastor revisa los textos bíblicos, adapta ejemplos, añade experiencias propias y ajusta el lenguaje a su congregación.\n\nTema reconocido: ${item.title} · Versión ${sermonVersion%item.variants.length+1} de ${item.variants.length}`);
 $('sOut').innerHTML=html;
}

function comms(){let e=esc(val('cEvent')||'Nuestra próxima actividad'),a=esc($('cAudience').value),tone=$('cTone').value,date=fmtDate($('cDate').value),time=$('cTime').value||'Hora por confirmar',p=esc(val('cPlace')||'Lugar por confirmar'),x=esc(val('cExtra')),b=`📅 ${date} · ⏰ ${time}\n📍 ${p}`;let open=tone==='Formal'?'Queremos extender una cordial invitación.':tone==='Juvenil'?'🔥 ¡Se viene algo buenísimo!':tone==='Enérgico'?'🙌 ¡Prepárate para vivir algo especial!':'✨ Hay momentos que vale la pena vivir juntos.';$('cOut').innerHTML=card('📱 WhatsApp',`${open}\n\n${e}\n${b}${x?`\n\n${x}`:''}\n\n❤️ Reserva este espacio y acompáñanos. ¡Será un gusto encontrarnos!`)+card('📸 Facebook / Instagram',`${open}\n\n${e}\n${b}${x?`\n\n${x}`:''}\n\nInvita a alguien y acompáñanos.\n\n#Comunidad #Juntos #SomosProtagonistas`)+card('📲 Historia / Estado',`✨ ${e.toUpperCase()}\n${date} · ${time}\n📍 ${p}\n\n¡Te esperamos! 🙌`)+card('🎤 Anuncio verbal',`Queremos invitar a ${a.toLowerCase()} a ${e}. Nos encontraremos el ${date} a las ${time} en ${p}. Agéndalo, invita a alguien y acompáñanos.`)+card('⏰ Recordatorio',`🔔 ¡Ya falta muy poco!\n\n${e}\n${b}\n\nPrepara tu agenda y acompáñanos. ❤️`)+card('🙏 Seguimiento',`❤️ Gracias por ser parte de ${e}.\n\nDeseamos que lo vivido continúe dando fruto durante esta semana.\n\n🙏 Sigamos creciendo juntos.`)}
function study(){let t=esc(val('bTopic')||'Fe'),a=esc($('bAudience').value),d=$('bDuration').value,m=matchTopic(t),refs=m?m.item.variants[0].supports:['Salmos 119:105','Santiago 1:22','2 Timoteo 3:16'];$('bOut').innerHTML=card('🎯 Propósito',`Al finalizar este estudio de ${d} minutos, ${a.toLowerCase()} podrá comprender un principio bíblico sobre “${t}” y definir una aplicación concreta.`)+card('📖 Referencias sugeridas',refs.join(' · '))+card('🧊 Conexión inicial',`¿Qué experiencia cotidiana relacionas con “${t}” y por qué?`)+card('📚 Ruta de aprendizaje',`1. OBSERVAR — ¿Qué dice el pasaje?\n2. COMPRENDER — ¿Qué enseña?\n3. CONECTAR — ¿Dónde aparece en nuestra realidad?\n4. APLICAR — ¿Qué cambia esta semana?`)+card('💬 Preguntas',`• ¿Qué idea llama más tu atención?\n• ¿Qué principio encontramos?\n• ¿Qué suele impedirnos vivirlo?\n• ¿Cuál sería una respuesta concreta?`)}
function meeting(){let typ=esc($('mType').value),g=esc(val('mGoal')||'avanzar con claridad como equipo'),d=+$('mDuration').value;$('mOut').innerHTML=card('🎯 Resultado esperado',`Al terminar esta reunión debemos haber avanzado en: ${g}, con máximo tres acuerdos, responsables y próximo paso.`)+card('⏱️ Agenda',`5 min — Propósito\n${Math.round(d*.22)} min — Escuchar\n${Math.round(d*.22)} min — Prioridades\n${Math.round(d*.3)} min — Soluciones y acuerdos\nCierre — Responsables y próximo paso`)+card('💬 Preguntas clave',`• ¿Qué funciona y debemos conservar?\n• ¿Qué dificulta avanzar?\n• ¿Qué debemos simplificar?\n• ¿Cuáles son las tres acciones prioritarias?`)+card('📱 WhatsApp posterior',`🙌 Gracias equipo por nuestra reunión de ${typ.toLowerCase()}.\n\n🎯 Nuestro foco fue: ${g}.\n\nRecordemos registrar cada acuerdo con responsable y próximo paso.`)}
function care(){let s=$('aSituation').value,m=$('aMoment').value;$('aOut').innerHTML=card('🎯 Objetivo',`Escuchar y comprender la situación “${s}” antes de intentar resolverla.\n\nMomento: ${m}.`)+card('🤝 Cómo comenzar',`“Quisiera conversar contigo porque me importa saber cómo estás. Primero quisiera escucharte.”`)+card('❓ Preguntas',`¿Cómo estás viviendo esta situación?\n¿Qué está siendo más difícil?\n¿Qué apoyo sería útil?\n¿Qué podría ser un próximo paso realista?`)+card('⚠️ Qué evitar',`Evita minimizar, diagnosticar, presionar o dar soluciones antes de comprender.`)+`<div class="panel closebox"><strong>Ahora guarda el teléfono y escucha.</strong><p>La persona es lo importante.</p></div>`}
function dev(){let t=esc(val('dTopic')||'Esperanza'),a=esc($('dAudience').value),days=+$('dDays').value,m=matchTopic(t),refs=m?m.item.variants[0].supports:['Salmos 119:105','Santiago 1:22','Romanos 12:2'],h='';for(let i=0;i<days;i++)h+=card(`🙏 Día ${i+1}`,`📖 ${refs[i%refs.length]}\n\nREFLEXIÓN\n“${t}” necesita pasar de la idea a la vida. Para ${a.toLowerCase()}, ¿qué verdad necesita convertirse hoy en una acción?\n\n🎯 ACCIÓN\nDa un paso pequeño y concreto durante las próximas 24 horas.\n\n🙏 ORACIÓN\nSeñor, ayúdame a comprender tu Palabra y vivirla con fe. Amén.`);$('dOut').innerHTML=h}

function clearModule(fields,out,defaults={}){fields.forEach(id=>{const el=$(id);if(!el)return;if(el.tagName==='SELECT')el.selectedIndex=0;else el.value=''});Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});if($(out))$(out).replaceChildren();window.scrollTo(0,0)}
function clearSermon(){sermonVersion=0;clearModule(['sTopic','sType','sAudience','sDuration','sDepth'],'sOut',{sDuration:'30',sDepth:'Equilibrado'})}
function clearComms(){clearModule(['cEvent','cAudience','cTone','cDate','cTime','cPlace','cExtra'],'cOut')}
function clearStudy(){clearModule(['bTopic','bAudience','bDuration'],'bOut',{bDuration:'45'})}
function clearMeeting(){clearModule(['mType','mGoal','mDuration','mSituation'],'mOut',{mDuration:'45'})}
function clearCare(){clearModule(['aSituation','aMoment'],'aOut')}
function clearDev(){clearModule(['dTopic','dAudience','dDays'],'dOut')}
function doLogin(){const c=val('code').toUpperCase();if(users[c]===$('pass').value){$('login').classList.add('hidden');$('shell').classList.remove('hidden');$('loginErr').textContent=''}else $('loginErr').textContent='Código o clave incorrectos.'}
function logout(){$('shell').classList.add('hidden');$('login').classList.remove('hidden');$('code').value='';$('pass').value='';$('loginErr').textContent='';show('home')}
document.addEventListener('click',e=>{
  const open=e.target.closest('[data-open]');
  if(open){
    const target=open.dataset.open;
    if(target && document.getElementById(target)) show(target);
    return;
  }
  const cp=e.target.closest('[data-copy]');
  if(cp){
    copyResult(cp);
    return;
  }
});

function updateLearnProgress(){
  const boxes=[...document.querySelectorAll('.learn-done')];
  const done=boxes.filter(x=>x.checked).length;
  const pct=Math.round((done/8)*100);
  const txt=document.getElementById('learnProgressText');
  const bar=document.getElementById('learnProgressBar');
  if(txt) txt.textContent=`${done} de 8 · ${pct}%`;
  if(bar) bar.style.width=`${pct}%`;
}
function loadLearnProgress(){
  document.querySelectorAll('.learn-done').forEach(el=>{
    try{ el.checked=localStorage.getItem(`pastoral_learn_done_${el.dataset.learnCh}`)==='1'; }catch(e){}
  });
  document.querySelectorAll('[data-learn-note]').forEach(el=>{
    try{ el.value=localStorage.getItem(`pastoral_learn_note_${el.dataset.learnNote}`)||''; }catch(e){}
  });
  updateLearnProgress();
}
function resetLearnProgress(){
  document.querySelectorAll('.learn-done').forEach(el=>{
    el.checked=false;
    try{localStorage.removeItem(`pastoral_learn_done_${el.dataset.learnCh}`)}catch(e){}
  });
  document.querySelectorAll('[data-learn-note]').forEach(el=>{
    el.value='';
    try{localStorage.removeItem(`pastoral_learn_note_${el.dataset.learnNote}`)}catch(e){}
  });
  updateLearnProgress();
}
document.addEventListener('change',e=>{
  if(e.target.classList.contains('learn-done')){
    try{localStorage.setItem(`pastoral_learn_done_${e.target.dataset.learnCh}`,e.target.checked?'1':'0')}catch(err){}
    updateLearnProgress();
  }
});
document.addEventListener('input',e=>{
  if(e.target.matches('[data-learn-note]')){
    try{localStorage.setItem(`pastoral_learn_note_${e.target.dataset.learnNote}`,e.target.value)}catch(err){}
  }
});

document.addEventListener('DOMContentLoaded',()=>{loadLearnProgress();$('login').classList.remove('hidden');$('shell').classList.add('hidden');$('pass')?.addEventListener('keydown',e=>{if(e.key==='Enter')doLogin()});});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js?v=2.6.3');


